input.sparql:
SELECT ?point ?name WHERE {
  ?point a brick:ElectricPower .
  OPTIONAL { ?point rdfs:label ?name }
  ?point ref:hasExternalReference ?series .
  ?series ref:hasTimeseriesId ?tsid .
}

SELECT DISTINCT ?class WHERE {
  ?point a ?class .
  FILTER (str(?class) LIKE "%lectric%" || str(?class) LIKE "%ower%")
}

SELECT ?point ?class ?tsid WHERE {
  ?point ref:hasExternalReference ?series .
  ?series ref:hasTimeseriesId ?tsid .
  ?point a ?class .
  FILTER (str(?class) LIKE "%ElectricPower%" || str(?class) LIKE "%ElectricEnergy%")
}
